import{_ as t}from"./chunks/plate-navigation.DRgsKBSY.js";import{_ as l,c as i,o as r,j as e,ag as o,a as s}from"./chunks/framework.DZ_cNctr.js";const v=JSON.parse('{"title":"HCS Plates","description":"","frontmatter":{},"headers":[],"relativePath":"guides/hcs-plates.md","filePath":"guides/hcs-plates.md"}'),n={name:"guides/hcs-plates.md"};function d(h,a,p,c,m,u){return r(),i("div",null,[...a[0]||(a[0]=[e("h1",{id:"hcs-plates",tabindex:"-1"},[s("HCS Plates "),e("a",{class:"header-anchor",href:"#hcs-plates","aria-label":'Permalink to "HCS Plates"'},"​")],-1),e("p",null,"Find Nuclei Viewer supports High-Content Screening (HCS) plate data in OME-ZARR format. Any plate format works: 96, 384, 1536-well, and custom layouts.",-1),e("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0",overflow:"hidden",margin:"1.5rem 0"}},[e("iframe",{src:"https://www.youtube.com/embed/tTUhXRHREnU?rel=0&modestbranding=1&vq=hd720&mute=1",title:"HCS Plate in Your Browser",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%",border:"0"},allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""})],-1),o('<h2 id="opening-a-plate" tabindex="-1">Opening a Plate <a class="header-anchor" href="#opening-a-plate" aria-label="Permalink to &quot;Opening a Plate&quot;">​</a></h2><p>Open an HCS plate the same way as any other OME-ZARR dataset. Drag and drop, or paste a URL. The viewer automatically detects plate metadata and adjusts the interface.</p><h2 id="navigation-levels" tabindex="-1">Navigation Levels <a class="header-anchor" href="#navigation-levels" aria-label="Permalink to &quot;Navigation Levels&quot;">​</a></h2><p>HCS plates have three viewing levels:</p><h3 id="field-view" tabindex="-1">Field View <a class="header-anchor" href="#field-view" aria-label="Permalink to &quot;Field View&quot;">​</a></h3><p>When a plate first loads, you see the first field of the first populated well. This is the same as viewing a regular single image: zoom, pan, adjust channels.</p><h3 id="grid-view" tabindex="-1">Grid View <a class="header-anchor" href="#grid-view" aria-label="Permalink to &quot;Grid View&quot;">​</a></h3><p>Click <strong>Show All Fields</strong> to see all fields in the current well arranged in a grid. This gives you a spatial overview of the entire well.</p><h3 id="plate-view" tabindex="-1">Plate View <a class="header-anchor" href="#plate-view" aria-label="Permalink to &quot;Plate View&quot;">​</a></h3><p>Click <strong>Show Full Plate</strong> to see the full plate layout. All populated wells are rendered as a grid, showing a preview of each well&#39;s content.</p><h2 id="well-navigation" tabindex="-1">Well Navigation <a class="header-anchor" href="#well-navigation" aria-label="Permalink to &quot;Well Navigation&quot;">​</a></h2><img src="'+t+'" alt="HCS plate navigation controls" style="max-width:320px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><p>In Plate View, click any well to jump to it. The viewer zooms into that well&#39;s fields.</p><h2 id="seamless-zoom" tabindex="-1">Seamless Zoom <a class="header-anchor" href="#seamless-zoom" aria-label="Permalink to &quot;Seamless Zoom&quot;">​</a></h2><p>The signature feature: zoom smoothly from the full plate overview all the way down to individual cells. The viewer handles multi-resolution tile loading across wells and fields transparently.</p><h2 id="channel-controls" tabindex="-1">Channel Controls <a class="header-anchor" href="#channel-controls" aria-label="Permalink to &quot;Channel Controls&quot;">​</a></h2><p>Channel settings (colors, contrast, visibility) apply across all wells and fields simultaneously. Change a channel color once and it updates plate-wide.</p><h2 id="labels-on-plates" tabindex="-1">Labels on Plates <a class="header-anchor" href="#labels-on-plates" aria-label="Permalink to &quot;Labels on Plates&quot;">​</a></h2><p>Segmentation labels can be loaded at the plate level. The viewer discovers shared label names across wells and renders them consistently.</p><h2 id="live-examples" tabindex="-1">Live Examples <a class="header-anchor" href="#live-examples" aria-label="Permalink to &quot;Live Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>Description</th></tr></thead><tbody><tr><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.5%2Fidr0090%2F190129.zarr&amp;z=15&amp;channels=0%3Aoff%3AFFFFFF%3A617%3A1676%2C1%3Aon%3A0000FF%3A403%3A441%2C2%3Aoff%3A00FF00%3A109%3A148%2C3%3Aon%3AFF0000%3A113%3A254%2C4%3Aon%3A00FF00%3A132%3A720&amp;zoom=-1.38&amp;center=1024%2C1022" target="_blank" rel="noreferrer">HCS Plate (v0.5, 5ch)</a></td><td>Multi-well plate, 5 channels, v0.5</td></tr><tr><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.4%2Fidr0072B%2F9512.zarr&amp;z=0&amp;channels=0%3Aon%3A00FF00%3A24%3A1835%2C1%3Aon%3A0000FF%3A6%3A843&amp;zoom=-0.38&amp;center=673%2C509" target="_blank" rel="noreferrer">HCS Plate (v0.4, 2ch)</a></td><td>Multi-well plate, 2 channels, v0.4</td></tr></tbody></table><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshots on this page use a plate from a public collection. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p>',23)])])}const w=l(n,[["render",d]]);export{v as __pageData,w as default};
